  metro = mk('metro'), cafew = mk('cafew'), girl1 = mk('girl1'), girl2 = mk('girl2'), coll = mk('coll'), kid = mk('kid'), kid2 = mk('kid2'), coach = mk('coach'), ref = mk('ref'), rival = mk('rival'), medic = mk('medic'), doc = mk('doc'), passer = mk('passer');
