for (const row of P) { const v = row[2]; if ((v.face?.tm || v.set === 'garages' || v.set === 'ward') && v.ui) for (const u of v.ui) { if (u.k === 'big' && u.y === 300) u.y = 960; if (u.k === 'thought') u.y = 970; } }

// ── сборка
const r2 = (x) => Math.round(x * 100) / 100;
const lineAt = (a, b) => W.filter((q) => q.start >= a - 0.05 && q.start < b - 0.05).map((q) => q.word).join(' ').trim();
const shots = P.map(([t, scene, v, extra = {}], i) => {
  const start = i === 0 ? 0 : r2(Math.max(0, t - 0.15));
  const end = i + 1 < P.length ? r2(P[i + 1][0] - 0.15) : DURATION;
  const set = v.set || (v.bp ? 'blueprint' : v.end ? 'end' : v.split ? 'split' : 'void');
  return { id: `s${String(i + 1).padStart(3, '0')}`, start, end, line: lineAt(start, end), scene, set, bars: null, in: extra.in || { type: 'cut' }, sfx: extra.sfx || [], amb: extra.amb || null, params: { v } };
});
for (let i = 1; i < shots.length; i++) if (shots[i].start <= shots[i - 1].start) throw new Error('порядок нарушен у ' + shots[i].id + ' ' + shots[i].scene);
const T = (s) => { const x = shots.find((x) => x.scene.startsWith(s)); if (!x) throw new Error('нет кадра ' + s); return x.start; };
